from common import ROWS
A('s1_la_nina','geo_pep_s1',4,3,'拉尼娜与赤道太平洋海气反馈','拉尼娜涉及赤道中东太平洋海表温度持续异常偏低的海气耦合状态。在典型模式中，赤道信风增强使暖表层水更偏向西侧，东部冷水上涌增强；气候影响具有地域和事件差异，不能等同于全球各地同时降温。','与厄尔尼诺比较赤道中东太平洋海温异常方向|说明增强信风与冷水上涌的反馈链',
Q('与厄尔尼诺的典型海温异常相比较，拉尼娜主要对应赤道中东太平洋哪种现象？','海表温度持续异常偏低','海表温度持续异常偏高','仅指一个城市某天低温','仅指海水盐度日变化','拉尼娜主要特征是相关赤道太平洋海域持续异常偏冷，厄尔尼诺典型状态相反；不能用单次城市天气代替海温监测。'),
Q('按典型赤道太平洋海气耦合模型，东风信风增强、暖表层水更向西输送时，东部海区更可能出现哪组变化？','冷水上涌增强，表层更易异常偏冷','冷水上涌减弱，表层更易异常偏暖','上涌增强必定使表层偏暖','风只影响大气，不会改变海水运动','增强的信风推动更多暖表层水向西，东部由较冷深层水补充，形成加强冷异常的典型过程；实际事件仍须监测。'),[D('s1_ocean_air','需先理解海温与风的双向耦合。'),D('s1_current_effects','需理解上升流输送深层海水的过程。')])
ROWS[-1]['source_evidence']={'source_url':'https://my.weather.gov.hk/sc/lrf/enso/enso-backgnd.htm','verification':'按官方配套目录定位至海—气相互作用；依据2025高中课标选择性必修1第1.8条补充，并核香港天文台官方ENSO背景资料。不声称已读取最新主教材对应页。'}
A('s3_lithium','geo_pep_s3',2,1,'战略矿产锂的地域类型与供应风险','锂用于锂离子电池等领域。中国地质调查局2025年公开资料列举西昆仑—松潘—甘孜锂辉石成矿带、盐湖型锂资源及江西等地锂云母利用进展，体现分布与矿床类型差异。资源发现不等于立即形成供应，加工技术、基础设施、成本和生态条件仍会约束产业链。','依据带年份官方实例识别锂矿类型和分布差异|分析从资源发现到稳定供应所需的环节',
Q('中国地质调查局2025年资料列举锂辉石型、盐湖型和锂云母型资源及不同地区进展，最直接说明什么？','锂资源有地域和赋存类型差异，利用工艺需匹配','所有锂矿都以同一形式集中在同一个省','找到锂资源就可跳过加工直接形成电池','锂辉石型与盐湖型必须采用完全相同流程','官方实例表明不同地区和矿床类型并存；开发利用需按原料特征选择适宜工艺和条件。'),
Q('某地新发现含锂矿床，企业据此宣称电池原料供应风险立即全部消失。主要遗漏了什么？','勘查、开采加工、运输和环境约束等后续环节','只要有地质资源就必定有足够成品库存','矿产在地下不需要品位与开采条件评价','需求增长会使任何矿床自然快速再生','资源基础改善可能降低部分风险，但稳定供应仍取决于技术、产能、运输、需求和生态约束。'),[D('s3_resource_security','矿产实例用于分析供应链风险。'),D('s3_resource_use','资源存在与可利用规模需要区分。')])
ROWS[-1]['source_evidence']={'source_url':'https://m.cgs.gov.cn/ddyw/202501/t20250108_779419.html','verification':'按配套目录定位至资源安全；补充2025课标选择性必修3第3.2条。实读中国地质调查局2025年锂矿资料，仅采用类型与分布实例，不将其储量或排名当作2026现状。'}
A('s3_china_cropland','geo_pep_s3',2,3,'中国耕地分布与质量差异','中国耕地的自然条件和生产能力存在区域差异。以2019年12月31日为标准时点的第三次全国国土调查公报显示，该调查时点64%的耕地位于秦岭—淮河以北，水田、水浇地和旱地并存，水热、坡度及灌排条件不同。调查时点不可省略，面积和地类也不能替代肥力、污染等质量指标。','从有日期的调查资料说明耕地分布差异|比较耕地面积、地类与综合质量指标',
Q('某学生引用2021年发布的第三次全国国土调查公报讨论耕地分布，资料标准时点为2019年12月31日。哪种标注正确？','说明这是2019年末时点的调查数据，不能直接当作2026实时数','直接标成2026年现状，因为今天正在阅读','把网页转载年份当作调查时点','只要出自官方，就可以省略所有年份','发布日期、转载日期与调查标准时点不同；动态土地利用数据必须注明真正对应的时间。'),
Q('中国甲乙两片耕地面积相同，甲为灌排良好的平缓耕地，乙坡度较大且有侵蚀风险。评价持续生产能力时应怎样做？','结合坡度、土壤、水源和灌排等质量条件比较','仅凭面积相等认定能力相同','只按行政区面积大小确定单产','只看距首都远近判断土壤质量','耕地生产与生态稳定性受多种自然和管理条件影响，数量相同不代表质量相同。'),[D('s3_food_security','需将耕地数量质量与粮食保障相联系。'),D('s2_compare','调查资料比较需要统一时间与指标口径。')])
ROWS[-1]['source_evidence']={'source_url':'https://www.ngcc.cn/xwzx/bnyw/202401/t20240110_2271.html','verification':'按配套目录定位至中国耕地与粮食安全；补充2025课标选择性必修3第3.3条。实读国家基础地理信息中心公开的三调联合公报耕地部分，调查时点2019-12-31，发布2021-08；不称最新实时耕地统计。'}
A('b2_marine_rights','geo_pep_b2',5,3,'海洋权益、资源利用与共同规则','海洋发展涉及资源、航运、科研和生态保护等利益。依据《联合国海洋法公约》，专属经济区在领海之外，沿海国对资源等享有规定的主权权利与管辖权，同时须适当顾及他国依公约享有的权利；不能把专属经济区与领海或陆地混同。','区分特定资源主权权利与无范围限制的领土主权|解释海洋资源利用需兼顾生态和其他合法使用',
Q('按《联合国海洋法公约》第55、56条，沿海国在专属经济区对自然资源的基本权利应怎样概括？','对勘探开发、养护管理等享有规定的主权权利','专属经济区与本国陆地在全部权利上完全相同','沿海国在该区对资源没有任何权利','有资源权利就不需要承担相关义务','公约区分特定主权权利、管辖权与其他权利义务；专属经济区不是与领土完全相同的法律空间。'),
Q('在无边界争议的相关海域规划资源开发，依据公约的概括原则，哪种思路较合理？','依法利用资源并考虑环境保护和其他合法海洋使用','仅凭预期收益排除所有其他合法使用','只讨论资源量，完全不考虑海洋生态','把享有资源权利理解为无需遵守共同规则','资源开发权利与环境等义务、其他国家的合法权利需要协调；本题不讨论具体海域划界。'),[D('j_marine_resource','海洋资源类型为权益与利用讨论提供背景。','soft'),D('b2_sustainable','海洋发展也需兼顾生态与社会目标。','soft')])
ROWS[-1]['source_evidence']={'source_url':'https://www.un.org/zh/documents/treaty/UNCLOS-1982','verification':'按配套目录定位至中国国家发展战略举例；补充2025课标必修地理2第2.8条。核联合国官方中文《海洋法公约》第55、56、58条，保持高中概括，不据此判断具体海域边界。'}
A('b2_curriculum_islands','geo_pep_b2',5,3,'中国课标中的海洋国土表述与资料归属','2025年中国高中地理课标“地理2”第2.9条将南海诸岛表述为中国领土的组成部分，并将钓鱼岛及其附属岛屿表述为中国固有领土。这是该中国课程标准的官方表述。阅读相关资料时应注明文本归属，区分课程要求、地理资料与各方立场，不能仅由一国课标推导国际各方已一致。','准确指出该中国课程标准列举的岛屿对象|区分对课程文本的复述与对国际共识的推断',
Q('依据2025年中国高中地理课标“地理2”第2.9条，该条明确列举的岛屿对象是哪一组？','南海诸岛与钓鱼岛及其附属岛屿','日本列岛与菲律宾群岛','夏威夷群岛与阿留申群岛','马尔代夫群岛与安达曼群岛','本题核对中国课程标准的明确教学对象，不把课标表述等同于对所有国际立场的总结。'),
Q('学生写道“某国课标这样表述，因此已证明国际各方没有任何不同立场”。哪种评价最准确？','课标能证明其课程表述，国际各方是否一致仍需另行核查','一国课标天然等同国际条约','岛屿名称译法相同就表示法律立场一致','地图比例尺足以决定所有主权问题','资料能支持的结论有边界；课程文本、国际文件和不同主体立场应分别核实，不能跨越证据作推断。'),[D('b2_marine_rights','相关海洋概念有助于区分不同类型表述。','soft')])
ROWS[-1]['source_evidence']={'source_url':'https://www.scmlzx.net/uploadfile/2025/1110/%EF%BC%887%EF%BC%89%E6%99%AE%E9%80%9A%E9%AB%98%E4%B8%AD%E5%9C%B0%E7%90%86%E8%AF%BE%E7%A8%8B%E6%A0%87%E5%87%86%E6%97%A5%E5%B8%B8%E4%BF%AE%E8%AE%A2%E7%89%88%EF%BC%882017%E5%B9%B4%E7%89%882025%E5%B9%B4%E4%BF%AE%E8%AE%A2%EF%BC%89.pdf','verification':'按官方配套目录作章节定位；实读学校正式公开转载的2025中国高中地理课标印刷页12、必修地理2第2.9条。明确归属中国课标，不作为国际各方一致的证据，也不声称最新主教材已逐页读完。'}
